// Real escrow client: calls the deployed Soroban contract on Stellar testnet.
// Uses the TypeScript bindings generated by `stellar contract bindings typescript`
// (src/contracts/escrow, do not edit by hand) and signs with the user's wallet.
import { nativeToScVal, rpc, scValToNative } from "@stellar/stellar-sdk";
import { Client, type Agreement as RawAgreement, type Milestone as RawMilestone } from "@/contracts/escrow";
import { ESCROW_CONTRACT_ID, NETWORK_PASSPHRASE, STELLAR_RPC_URL, USDC_CODE, USDC_ISSUER } from "./config";
import { getAccountBalances } from "./stellarAccount";
import type { ActivityItem, ActivityKind, Agreement, Config, Milestone, MilestoneStatus } from "./types";
import { getConnectedWallet, signWithWallet } from "./wallet";
import type { EscrowApi, NewAgreementInput } from "./escrow";

const MAX_SCAN = 500;

function toStatus(s: unknown): MilestoneStatus {
  if (typeof s === "string") return s as MilestoneStatus;
  if (s && typeof s === "object" && "tag" in s) return (s as { tag: MilestoneStatus }).tag;
  return "Pending";
}

function toMilestone(m: RawMilestone): Milestone {
  return {
    title: m.title,
    amount: Number(m.amount),
    status: toStatus(m.status),
    evidence: m.evidence,
    submittedAt: Number(m.submitted_at),
    disputeReason: m.dispute_reason,
  };
}

function toAgreement(a: RawAgreement): Agreement {
  return {
    id: Number(a.id),
    freelancer: a.freelancer,
    client: a.client,
    title: a.title,
    reviewWindowSecs: Number(a.review_window_secs),
    feeBps: Number(a.fee_bps),
    milestones: a.milestones.map(toMilestone),
    createdAt: Number(a.created_at),
  };
}

const baseOptions = {
  contractId: ESCROW_CONTRACT_ID,
  networkPassphrase: NETWORK_PASSPHRASE,
  rpcUrl: STELLAR_RPC_URL,
};

export class RealEscrow implements EscrowApi {
  private reader = new Client(baseOptions);
  lastTxHash: string | null = null;

  /** Client that signs with the connected wallet. */
  private signer(): Client {
    const w = getConnectedWallet();
    if (!w) throw new Error("NoWallet");
    return new Client({
      ...baseOptions,
      publicKey: w.address,
      signTransaction: (xdr, opts) => signWithWallet(xdr, { ...opts, address: w.address }),
    });
  }

  private async send<T>(build: (c: Client) => Promise<{ signAndSend: () => Promise<{ result: T; sendTransactionResponse?: { hash: string } }> }>): Promise<T> {
    const tx = await build(this.signer());
    const sent = await tx.signAndSend();
    this.lastTxHash = sent.sendTransactionResponse?.hash ?? null;
    return sent.result;
  }

  async getConfig(): Promise<Config> {
    const c = (await this.reader.get_config()).result.unwrap();
    return {
      admin: c.admin,
      arbiter: c.arbiter,
      token: c.token,
      feeBps: Number(c.fee_bps),
      feeRecipient: c.fee_recipient,
    };
  }

  async getAgreement(id: number): Promise<Agreement | null> {
    const res = (await this.reader.get_agreement({ agreement_id: BigInt(id) })).result;
    if (res.isErr()) return null;
    return toAgreement(res.unwrap());
  }

  async agreementsOf(address: string): Promise<Agreement[]> {
    const [asF, asC] = await Promise.all([
      this.reader.agreements_of_freelancer({ address }),
      this.reader.agreements_of_client({ address }),
    ]);
    const ids = Array.from(new Set([...asF.result, ...asC.result].map((x) => Number(x)))).sort((a, b) => b - a);
    const list = await Promise.all(ids.map((id) => this.getAgreement(id)));
    return list.filter((a): a is Agreement => a !== null);
  }

  /** The contract has no "list all"; ids are sequential from 0, so read until the first gap. */
  async listAll(): Promise<Agreement[]> {
    const out: Agreement[] = [];
    for (let id = 0; id < MAX_SCAN; id++) {
      const a = await this.getAgreement(id);
      if (!a) break;
      out.push(a);
    }
    return out.reverse();
  }

  /** Reads this agreement's events (contracts/escrow/src/events.rs) from Stellar RPC, which keeps about a week of history. */
  async activity(id: number): Promise<ActivityItem[]> {
    const agreement = await this.getAgreement(id);
    if (!agreement) return [];
    const server = new rpc.Server(STELLAR_RPC_URL);
    const latest = (await server.getLatestLedger()).sequence;
    const idTopic = nativeToScVal(BigInt(id), { type: "u64" }).toXDR("base64");
    const filters = [
      { type: "contract" as const, contractIds: [ESCROW_CONTRACT_ID], topics: [["*", idTopic]] },
      { type: "contract" as const, contractIds: [ESCROW_CONTRACT_ID], topics: [["*", idTopic, "*"]] },
    ];
    // Ledgers close about every 5 seconds: start a little before the agreement was created.
    const age = Math.max(0, Math.floor(Date.now() / 1000) - agreement.createdAt);
    let start = Math.max(1, latest - Math.ceil(age / 4) - 500);
    // Each RPC call scans a limited window of ledgers (about 10,000), so follow the cursor.
    const pages = Math.min(40, Math.ceil((latest - start) / 10_000) + 1);
    const events: rpc.Api.EventResponse[] = [];
    let cursor: string | undefined;
    for (let p = 0; p < pages; p++) {
      let res: rpc.Api.GetEventsResponse;
      try {
        res = cursor
          ? await server.getEvents({ cursor, filters, limit: 200 })
          : await server.getEvents({ startLedger: start, filters, limit: 200 });
      } catch (e) {
        // Start is older than what the RPC keeps: move it forward and retry once.
        if (!cursor && /startLedger|range/i.test(String(e))) {
          start = latest - 100_000;
          continue;
        }
        throw e;
      }
      events.push(...res.events);
      if (res.cursor === cursor) break;
      cursor = res.cursor;
    }
    return events
      .map((e) => {
        const kind = String(scValToNative(e.topic[0])) as ActivityKind;
        const index = e.topic[2] ? Number(scValToNative(e.topic[2])) : undefined;
        return { kind, index, at: Math.floor(Date.parse(e.ledgerClosedAt) / 1000), txHash: e.txHash };
      })
      .sort((x, y) => x.at - y.at);
  }

  async balanceOf(address: string): Promise<number> {
    const b = await getAccountBalances(address);
    return b.usdc ?? 0;
  }

  async createAgreement(input: NewAgreementInput): Promise<number> {
    const res = await this.send((c) =>
      c.create_agreement({
        freelancer: input.freelancer,
        client: input.client,
        title: input.title,
        milestones: input.milestones.map((m) => ({ title: m.title, amount: BigInt(m.amount) })),
        review_window_secs: BigInt(input.reviewWindowSecs),
      }),
    );
    return Number(res.unwrap());
  }

  async fundMilestone(id: number, index: number): Promise<void> {
    (await this.send((c) => c.fund_milestone({ agreement_id: BigInt(id), index }))).unwrap();
  }

  async submitMilestone(id: number, index: number, evidence: string): Promise<void> {
    (await this.send((c) => c.submit_milestone({ agreement_id: BigInt(id), index, evidence }))).unwrap();
  }

  async approveMilestone(id: number, index: number): Promise<void> {
    (await this.send((c) => c.approve_milestone({ agreement_id: BigInt(id), index }))).unwrap();
  }

  async claimMilestone(id: number, index: number): Promise<void> {
    (await this.send((c) => c.claim_milestone({ agreement_id: BigInt(id), index }))).unwrap();
  }

  async disputeMilestone(id: number, index: number, reason: string): Promise<void> {
    (await this.send((c) => c.dispute_milestone({ agreement_id: BigInt(id), index, reason }))).unwrap();
  }

  async resolveDispute(id: number, index: number, freelancerBps: number): Promise<void> {
    (await this.send((c) => c.resolve_dispute({ agreement_id: BigInt(id), index, freelancer_bps: freelancerBps }))).unwrap();
  }

  async refundMilestone(id: number, index: number): Promise<void> {
    (await this.send((c) => c.refund_milestone({ agreement_id: BigInt(id), index }))).unwrap();
  }
}

export const USDC_ASSET_LABEL = `${USDC_CODE}:${USDC_ISSUER}`;
